// Responses built in JavaScript and served by Bun.serve: the content-type each one sends, read off
// the wire with a raw socket (issue #71). tests/npm/bun_content_type.stdout is this package's
// output under Bun (`bun -e 'require("bun-content-type")().then(() => {})'` from tests/npm).
const net = require("node:net");

const blob = (type) => new Blob(["x"], type === undefined ? {} : { type });
const form = () => {
  const f = new FormData();
  f.append("a", "1");
  return f;
};

const cases = {
  string: () => new Response("x"),
  number: () => new Response(5),
  json: () => Response.json({ a: 1 }),
  "json, the caller's type": () => Response.json({}, { headers: { "content-type": "application/vnd+json" } }),
  "json, its type deleted": () => {
    const r = Response.json(1);
    r.headers.delete("content-type");
    return r;
  },
  "url-encoded": () => new Response(new URLSearchParams("a=1")),
  multipart: () => new Response(form()),
  "blob text/html": () => new Response(blob("text/html")),
  "blob text/html;charset=latin1": () => new Response(blob("text/html;charset=latin1")),
  "blob text/css": () => new Response(blob("text/css")),
  "blob application/json": () => new Response(blob("application/json")),
  "blob application/javascript": () => new Response(blob("application/javascript")),
  "blob text/csv": () => new Response(blob("text/csv")),
  "blob TEXT/PLAIN": () => new Response(blob("TEXT/PLAIN")),
  "blob image/svg+xml": () => new Response(blob("image/svg+xml")),
  "blob image/png": () => new Response(blob("image/png")),
  "blob application/x-custom": () => new Response(blob("application/x-custom")),
  "blob, no type": () => new Response(blob()),
  "file, no type": () => new Response(new File(["x"], "a.txt")),
  "blob type deleted": () => {
    const r = new Response(blob("text/css"));
    r.headers.delete("content-type");
    return r;
  },
  Uint8Array: () => new Response(new Uint8Array([120])),
  ArrayBuffer: () => new Response(new ArrayBuffer(1)),
  stream: () => new Response(new ReadableStream({ start(c) { c.enqueue(new TextEncoder().encode("x")); c.close(); } })),
  "no body": () => new Response(null),
  "an explicit text/plain": () => new Response("x", { headers: { "content-type": "text/plain" } }),
  "set to the default after": () => {
    const r = new Response("x");
    r.headers.set("content-type", "text/plain;charset=UTF-8");
    return r;
  },
  "appended after": () => {
    const r = new Response("x");
    r.headers.delete("content-type");
    r.headers.append("content-type", "text/plain;charset=UTF-8");
    return r;
  },
  "a clone": () => new Response("x").clone(),
  "a clone of json": () => Response.json(1).clone(),
  "a clone, set after": () => {
    const r = new Response("x");
    r.headers.set("content-type", "text/plain;charset=UTF-8");
    return r.clone();
  },
};

// one request on a fresh connection: the response's content-type lines, and its body
function get(port, path) {
  return new Promise((resolve, reject) => {
    const s = net.connect(port, "127.0.0.1", () => {
      s.write(`GET ${path} HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n`);
    });
    const chunks = [];
    s.on("data", (c) => chunks.push(c));
    s.on("error", reject);
    s.on("close", () => {
      const text = Buffer.concat(chunks).toString("latin1");
      const at = text.indexOf("\r\n\r\n");
      const types = text.slice(0, at).split("\r\n").filter((l) => /^content-type:/i.test(l)).map((l) => l.slice(13).trim());
      resolve([types, text.slice(at + 4)]);
    });
  });
}

module.exports = async function run() {
  const names = Object.keys(cases);
  const upstream = Bun.serve({
    port: 0,
    fetch: () => new Response("x", { headers: { "content-type": "text/plain;charset=UTF-8" } }),
  });
  const server = Bun.serve({
    port: 0,
    async fetch(req) {
      const name = decodeURIComponent(new URL(req.url).pathname.slice(1));
      // (a fetched response served as it is: its content-type exactly as it came)
      if (name === "a fetched response") return fetch(`http://127.0.0.1:${upstream.port}/`);
      return cases[name]();
    },
  });
  for (const name of [...names, "a fetched response"]) {
    const [types, body] = await get(server.port, "/" + encodeURIComponent(name));
    let shown = types.length === 0 ? "(none)" : types.join(" | ");
    if (name === "multipart") {
      // (the boundary is random: it must be there, and be the body's)
      const b = /boundary=(.+)$/.exec(types[0] ?? "")?.[1];
      shown = shown.replace(b, "B") + (b && body.includes(`--${b}`) ? " (the body's boundary)" : " (NOT the body's boundary)");
    }
    console.log(`${name}: ${shown}`);
  }
  server.stop(true);
  upstream.stop(true);
};
